using BusinessOS.Desktop.ViewModels;
using BusinessOS.Modules.BusinessProjects.Application;
using BusinessOS.Modules.Companies.Application;
using BusinessOS.Modules.Budgeting.Application;
using FluentAssertions;
using Xunit;
namespace BusinessOS.UnitTests;

public sealed class BusinessProjectsWorkspaceTests
{
    private static CompanyLookupItem Company(Guid? id = null) => new(id ?? Guid.NewGuid(), "Firma", "PLN", CompanyStatusValue.Active);
    private static BusinessProjectListItem Project(BusinessProjectStatusValue status = BusinessProjectStatusValue.Draft, Guid? id = null, long version = 1) => new(id ?? Guid.NewGuid(), Guid.NewGuid(), "Projekt", "Gym", "Lodz", status, new(2026, 1, 1), new(2026, 2, 1), "PLN", DateTimeOffset.UtcNow, version);
    private static BusinessProjectDetails Details(BusinessProjectListItem p, params BusinessProjectStatusValue[] allowed) => new(p.Id, p.CompanyId, p.Name, p.BusinessType, p.Location, "", p.Status, p.PlannedStartDate, p.PlannedOpeningDate, p.BaseCurrency, DateTimeOffset.UtcNow, p.UpdatedAtUtc, Guid.NewGuid(), Guid.NewGuid(), p.Version, allowed);
    private static BudgetingViewModel Budget() => new(new FakeBudgeting(), new FakeBudgetLookup());
    private static ActualCostsViewModel Actual() => new(new FakeActualCosts(), new FakeBudgetLookup(), TimeProvider.System);
    private static ForecastCostsViewModel Forecast() => new(new FakeForecastCosts(), new FakeBudgetLookup(), TimeProvider.System);
    private static BudgetVarianceViewModel Variance(FakeBudgetLookup? lookup = null, FakeVariance? service = null) => new(service ?? new(), lookup ?? new());
    private static CostCashFlowViewModel CashFlow(FakeCashFlow? service = null, FakeBudgetLookup? lookup = null) => new(service ?? new(), lookup ?? new());
    private static BudgetForecastViewModel ForecastAnalytics() => new(new FakeBudgetForecast(), new FakeBudgetLookup());
    [Fact] public async Task Reload_companies_selects_single_company_and_loads_projects() { var c = Company(); var crud = new FakeProjects { Listed = [Project()] }; var vm = new BusinessProjectsViewModel(crud, new FakeLookup { Items = [c] }, TimeProvider.System); await vm.ReloadCompaniesAsync(); vm.SelectedCompany!.Id.Should().Be(c.Id); vm.Projects.Should().HaveCount(1); vm.LastCompaniesReloadSucceeded.Should().BeTrue(); }
    [Fact] public async Task Reload_preserves_existing_company_and_clears_removed_company() { var a = Company(); var b = Company(); var lookup = new FakeLookup { Items = [a, b] }; var vm = new BusinessProjectsViewModel(new FakeProjects(), lookup, TimeProvider.System); await vm.ReloadCompaniesAsync(); await vm.SelectCompanyAsync(a); await vm.ReloadCompaniesAsync(); vm.SelectedCompany!.Id.Should().Be(a.Id); lookup.Items = [b]; await vm.ReloadCompaniesAsync(); vm.SelectedCompany.Should().BeNull(); vm.Projects.Should().BeEmpty(); vm.OperationMessage.Should().Contain("nie jest już dostępna"); }
    [Fact] public async Task Status_button_is_available_before_transitions_are_loaded_and_terminal_projects_disable_it() { var c = Company(); var draft = Project(); var crud = new FakeProjects { Listed = [draft], Details = Details(draft, BusinessProjectStatusValue.Analysis) }; var vm = new BusinessProjectsViewModel(crud, new FakeLookup { Items = [c] }, TimeProvider.System); await vm.ReloadCompaniesAsync(); vm.SelectedProject = draft; vm.CanChangeStatus.Should().BeTrue(); await vm.OpenStatusDialogAsync(); vm.IsStatusDialogOpen.Should().BeTrue(); vm.AllowedTransitions.Should().Equal(BusinessProjectStatusValue.Analysis); vm.CloseStatusDialog(); vm.SelectedProject = Project(BusinessProjectStatusValue.Closed); vm.CanChangeStatus.Should().BeFalse(); vm.SelectedProject = Project(BusinessProjectStatusValue.Cancelled); vm.CanChangeStatus.Should().BeFalse(); }
    [Fact] public async Task Archive_uses_identity_captured_when_dialog_opened() { var c = Company(); var first = Project(id: Guid.NewGuid(), version: 7); var second = Project(); var crud = new FakeProjects { Listed = [first, second] }; var vm = new BusinessProjectsViewModel(crud, new FakeLookup { Items = [c] }, TimeProvider.System); await vm.ReloadCompaniesAsync(); vm.SelectedProject = first; vm.OpenArchiveDialog(); vm.SelectedProject = second; vm.SelectedProject!.Id.Should().Be(first.Id); await vm.ConfirmArchiveAsync(); crud.Archived.Should().Be(new ArchiveBusinessProjectRequest(first.Id, 7)); vm.IsArchiveDialogOpen.Should().BeFalse(); }
    [Fact] public async Task Explicit_all_filter_can_be_restored_after_specific_filter() { var c = Company(); var vm = new BusinessProjectsViewModel(new FakeProjects(), new FakeLookup { Items = [c] }, TimeProvider.System); await vm.ReloadCompaniesAsync(); await vm.SelectStatusFilterAsync(vm.StatusFilters.Single(x => x.Value == BusinessProjectStatusValue.Analysis)); await vm.SelectStatusFilterAsync(vm.StatusFilters[0]); vm.SelectedStatusFilter.Value.Should().BeNull(); }
    [Fact] public async Task Navigate_to_projects_waits_for_company_reload_and_stays_on_failure() { var lookup = new FakeLookup { Gate = new() }; var projects = new BusinessProjectsViewModel(new FakeProjects(), lookup, TimeProvider.System); var workspace = new MainWorkspaceViewModel(new CompaniesViewModel(new FakeCompanies()), projects, Budget(), Actual(), Forecast(), Variance(), ForecastAnalytics(), CashFlow()); var navigation = workspace.NavigateAsync(WorkspaceSection.BusinessProjects); workspace.SelectedSection.Should().Be(WorkspaceSection.Companies); lookup.Gate.SetResult([Company()]); await navigation; workspace.SelectedSection.Should().Be(WorkspaceSection.BusinessProjects); var failedProjects = new BusinessProjectsViewModel(new FakeProjects(), new FakeLookup { Failure = true }, TimeProvider.System); var failed = new MainWorkspaceViewModel(new CompaniesViewModel(new FakeCompanies()), failedProjects, Budget(), Actual(), Forecast(), Variance(), ForecastAnalytics(), CashFlow()); await failed.NavigateAsync(WorkspaceSection.BusinessProjects); failed.SelectedSection.Should().Be(WorkspaceSection.Companies); }
    [Fact] public async Task Explicit_company_and_filter_selection_reload_without_fire_and_forget() { var a = Company(); var b = Company(); var crud = new FakeProjects(); var vm = new BusinessProjectsViewModel(crud, new FakeLookup { Items = [a, b] }, TimeProvider.System); await vm.ReloadCompaniesAsync(); await vm.SelectCompanyAsync(b); vm.SelectedCompany!.Id.Should().Be(b.Id); await vm.SelectStatusFilterAsync(vm.StatusFilters.Single(x => x.Value == BusinessProjectStatusValue.Analysis)); vm.SelectedStatusFilter.Value.Should().Be(BusinessProjectStatusValue.Analysis); await vm.SelectStatusFilterAsync(vm.StatusFilters[0]); vm.SelectedStatusFilter.Value.Should().BeNull(); }
    [Fact] public async Task Editor_and_dialogs_lock_company_project_filter_navigation_and_recovery() { var c = Company(); var p = Project(); var crud = new FakeProjects { Listed = [p], Details = Details(p, BusinessProjectStatusValue.Analysis) }; var vm = new BusinessProjectsViewModel(crud, new FakeLookup { Items = [c] }, TimeProvider.System); var workspace = new MainWorkspaceViewModel(new CompaniesViewModel(new FakeCompanies()), vm, Budget(), Actual(), Forecast(), Variance(), ForecastAnalytics(), CashFlow()); await vm.ReloadCompaniesAsync(); vm.BeginCreate(); vm.CanCancel.Should().BeTrue(); vm.CanSelectCompany.Should().BeFalse(); vm.CanSelectProject.Should().BeFalse(); vm.CanChangeFilter.Should().BeFalse(); workspace.CanNavigate.Should().BeFalse(); workspace.CanOpenRecovery.Should().BeFalse(); vm.CancelEditor(); vm.SelectedProject = p; await vm.OpenStatusDialogAsync(); vm.IsStatusDialogOpen.Should().BeTrue(); vm.CanSelectProject.Should().BeFalse(); workspace.CanOpenRecovery.Should().BeFalse(); vm.CloseStatusDialog(); vm.OpenArchiveDialog(); vm.IsArchiveDialogOpen.Should().BeTrue(); vm.CanSelectCompany.Should().BeFalse(); workspace.CanNavigate.Should().BeFalse(); vm.CloseArchiveDialog(); workspace.CanNavigate.Should().BeTrue(); }
    [Fact] public async Task Capability_notifications_are_raised_when_interaction_state_changes() { var c = Company(); var vm = new BusinessProjectsViewModel(new FakeProjects(), new FakeLookup { Items = [c] }, TimeProvider.System); await vm.ReloadCompaniesAsync(); var names = new List<string?>(); vm.PropertyChanged += (_, e) => names.Add(e.PropertyName); vm.BeginCreate(); names.Should().Contain([nameof(vm.CanCancel), nameof(vm.CanSelectCompany), nameof(vm.CanSelectProject), nameof(vm.CanChangeFilter), nameof(vm.CanNavigate)]); names.Clear(); vm.CancelEditor(); names.Should().Contain(nameof(vm.CanCancel)).And.Contain(nameof(vm.CanNavigate)); }
    [Fact] public async Task Company_selection_commits_company_and_projects_atomically() { var a = Company(); var b = Company(); var old = Project(); var fresh = Project(); var crud = new FakeProjects { ByCompany = new() { [a.Id] = [old], [b.Id] = [fresh] } }; var vm = new BusinessProjectsViewModel(crud, new FakeLookup { Items = [a, b] }, TimeProvider.System); await vm.ReloadCompaniesAsync(); await vm.SelectCompanyAsync(a); var gate = new TaskCompletionSource<IReadOnlyList<BusinessProjectListItem>>(); crud.Gate = gate; var selecting = vm.SelectCompanyAsync(b); vm.SelectedCompany!.Id.Should().Be(a.Id); vm.Projects.Should().Equal(old); gate.SetResult([fresh]); await selecting; vm.SelectedCompany!.Id.Should().Be(b.Id); vm.Projects.Should().Equal(fresh); }
    [Fact] public async Task Failed_or_cancelled_company_selection_preserves_previous_state_and_notifies_binding() { var a = Company(); var b = Company(); var old = Project(); var crud = new FakeProjects { ByCompany = new() { [a.Id] = [old] } }; var vm = new BusinessProjectsViewModel(crud, new FakeLookup { Items = [a, b] }, TimeProvider.System); await vm.ReloadCompaniesAsync(); await vm.SelectCompanyAsync(a); var notified = 0; vm.PropertyChanged += (_, e) => { if (e.PropertyName == nameof(vm.SelectedCompany)) notified++; }; crud.Failure = true; await vm.SelectCompanyAsync(b); vm.SelectedCompany!.Id.Should().Be(a.Id); vm.Projects.Should().Equal(old); notified.Should().BePositive(); crud.Failure = false; crud.Cancel = true; await vm.SelectCompanyAsync(b, new CancellationToken(true)); vm.SelectedCompany!.Id.Should().Be(a.Id); vm.Projects.Should().Equal(old); await vm.SelectCompanyAsync(null); vm.SelectedCompany.Should().BeNull(); vm.Projects.Should().BeEmpty(); }
    [Fact] public async Task Filter_change_is_atomic_and_failed_change_restores_binding() { var c = Company(); var draft = Project(); var analysis = Project(BusinessProjectStatusValue.Analysis); var crud = new FakeProjects { Listed = [draft, analysis] }; var vm = new BusinessProjectsViewModel(crud, new FakeLookup { Items = [c] }, TimeProvider.System); await vm.ReloadCompaniesAsync(); var analysisOption = vm.StatusFilters.Single(x => x.Value == BusinessProjectStatusValue.Analysis); await vm.SelectStatusFilterAsync(analysisOption); vm.Projects.Should().Equal(analysis); var notified = 0; vm.PropertyChanged += (_, e) => { if (e.PropertyName == nameof(vm.SelectedStatusFilter)) notified++; }; crud.Failure = true; await vm.SelectStatusFilterAsync(vm.StatusFilters[0]); vm.SelectedStatusFilter.Should().BeSameAs(analysisOption); vm.Projects.Should().Equal(analysis); notified.Should().BePositive(); }
    [Fact] public async Task Company_archive_captures_identity_and_locks_workspace() { var company = new CompanyListItem(Guid.NewGuid(), "Legal", "Captured", null, "PL", "PLN", CompanyStatusValue.Active, DateTimeOffset.UtcNow, 7); var service = new CapturingCompanies { Listed = [company] }; var companies = new CompaniesViewModel(service); await companies.RefreshAsync(); companies.SelectedCompany = company; var projects = new BusinessProjectsViewModel(new FakeProjects(), new FakeLookup(), TimeProvider.System); var workspace = new MainWorkspaceViewModel(companies, projects, Budget(), Actual(), Forecast(), Variance(), ForecastAnalytics(), CashFlow()); companies.OpenArchiveDialog(); companies.ArchivingCompanyName.Should().Be("Captured"); companies.CanSelectList.Should().BeFalse(); workspace.CanNavigate.Should().BeFalse(); workspace.CanOpenRecovery.Should().BeFalse(); companies.SelectedCompany = null; await companies.ConfirmArchiveAsync(); service.Archived.Should().Be(new ArchiveCompanyRequest(company.Id, 7)); companies.IsArchiveDialogOpen.Should().BeFalse(); workspace.CanNavigate.Should().BeTrue(); }
    [Fact] public async Task Cancelled_filter_keeps_filter_projects_and_selection() { var c = Company(); var selected = Project(BusinessProjectStatusValue.Analysis); var crud = new FakeProjects { Listed = [selected] }; var vm = new BusinessProjectsViewModel(crud, new FakeLookup { Items = [c] }, TimeProvider.System); await vm.ReloadCompaniesAsync(); vm.SelectedProject = selected; var original = vm.SelectedStatusFilter; crud.Cancel = true; await vm.SelectStatusFilterAsync(vm.StatusFilters.Single(x => x.Value == BusinessProjectStatusValue.Analysis), new(true)); vm.SelectedStatusFilter.Should().BeSameAs(original); vm.Projects.Should().Equal(selected); vm.SelectedProject.Should().BeSameAs(selected); }
    [Theory][InlineData(CompanyOperationStatus.ConcurrencyConflict)][InlineData(CompanyOperationStatus.PersistenceFailure)][InlineData(CompanyOperationStatus.Cancelled)] public async Task Company_archive_every_controlled_result_clears_captured_state(CompanyOperationStatus status) { var company = new CompanyListItem(Guid.NewGuid(), "Legal", "Captured", null, "PL", "PLN", CompanyStatusValue.Active, DateTimeOffset.UtcNow, 4); var service = new CapturingCompanies { Listed = [company], Status = status }; var vm = new CompaniesViewModel(service); await vm.RefreshAsync(); vm.SelectedCompany = company; vm.OpenArchiveDialog(); await vm.ConfirmArchiveAsync(); vm.IsArchiveDialogOpen.Should().BeFalse(); vm.ArchivingCompanyName.Should().BeNull(); vm.CanOpenRecovery.Should().BeTrue(); }
    [Fact]
    public async Task Navigate_to_budgeting_reloads_projects_before_switch_and_failure_keeps_companies()
    {
        var lookup = new FakeBudgetLookup { Items = [new(Guid.NewGuid(), "Gym", "PLN", true)] }; var budgeting = new BudgetingViewModel(new FakeBudgeting(), lookup);
        var workspace = new MainWorkspaceViewModel(new CompaniesViewModel(new FakeCompanies()), new BusinessProjectsViewModel(new FakeProjects(), new FakeLookup(), TimeProvider.System), budgeting, Actual(), Forecast(), Variance(), ForecastAnalytics(), CashFlow());
        await workspace.NavigateAsync(WorkspaceSection.Budgeting); lookup.Calls.Should().Be(1); workspace.SelectedSection.Should().Be(WorkspaceSection.Budgeting);
        var failedLookup = new FakeBudgetLookup { Failure = true }; var failed = new MainWorkspaceViewModel(new CompaniesViewModel(new FakeCompanies()), new BusinessProjectsViewModel(new FakeProjects(), new FakeLookup(), TimeProvider.System), new(new FakeBudgeting(), failedLookup), Actual(), Forecast(), Variance(), ForecastAnalytics(), CashFlow());
        await failed.NavigateAsync(WorkspaceSection.Budgeting); failed.SelectedSection.Should().Be(WorkspaceSection.Companies);
    }
    [Fact]
    public async Task Budget_editor_blocks_workspace_navigation_and_recovery_until_cancelled()
    {
        var project = new BudgetProjectInfo(Guid.NewGuid(), "Gym", "PLN", true); var budgeting = new BudgetingViewModel(new FakeBudgeting(), new FakeBudgetLookup { Items = [project] });
        var workspace = new MainWorkspaceViewModel(new CompaniesViewModel(new FakeCompanies()), new BusinessProjectsViewModel(new FakeProjects(), new FakeLookup(), TimeProvider.System), budgeting, Actual(), Forecast(), Variance(), ForecastAnalytics(), CashFlow());
        await budgeting.InitializeAsync(); await budgeting.SelectProjectAsync(project); budgeting.BeginCreateBudget();
        workspace.CanNavigate.Should().BeFalse(); workspace.CanOpenRecovery.Should().BeFalse(); budgeting.CancelBudgetEditor(); workspace.CanNavigate.Should().BeTrue();
    }
    [Fact]
    public async Task Actual_costs_navigation_reloads_before_switch_and_interaction_blocks_workspace()
    {
        var project = new BudgetProjectInfo(Guid.NewGuid(), "Gym", "PLN", true);
