        await actual.SelectProjectAsync(project); actual.BeginAddCost(); workspace.CanNavigate.Should().BeFalse(); workspace.CanOpenRecovery.Should().BeFalse(); actual.CancelEditor(); workspace.CanNavigate.Should().BeTrue();
    }
