        forecast.BeginAddForecast(); workspace.CanNavigate.Should().BeFalse(); workspace.CanOpenRecovery.Should().BeFalse(); forecast.CancelEditor(); await forecast.SelectForecastAsync(item); forecast.OpenArchiveDialog(); workspace.CanNavigate.Should().BeFalse(); workspace.CanOpenRecovery.Should().BeFalse(); forecast.CancelArchive(); workspace.CanNavigate.Should().BeTrue();
