    [Fact]
    public async Task Busy_forecast_costs_blocks_global_navigation_and_recovery()
    {
        var project = new BudgetProjectInfo(Guid.NewGuid(), "Gym", "PLN", true); var service = new FakeForecastCosts(); var forecast = new ForecastCostsViewModel(service, new FakeBudgetLookup { Items = [project] }, TimeProvider.System); var workspace = new MainWorkspaceViewModel(new(new FakeCompanies()), new(new FakeProjects(), new FakeLookup(), TimeProvider.System), Budget(), Actual(), forecast, Variance(), ForecastAnalytics(), CashFlow());
        await forecast.ReloadProjectsAsync(); await forecast.SelectProjectAsync(project); service.ListGate = new(TaskCreationOptions.RunContinuationsAsynchronously);
        var refresh = forecast.RefreshAsync(); forecast.IsBusy.Should().BeTrue(); workspace.CanNavigate.Should().BeFalse(); workspace.CanOpenRecovery.Should().BeFalse();
        service.ListGate.SetResult([]); await refresh; forecast.IsBusy.Should().BeFalse(); workspace.CanNavigate.Should().BeTrue(); workspace.CanOpenRecovery.Should().BeTrue();
    }
