    [Fact]
    public async Task Cost_cash_flow_navigation_waits_for_reload_and_failure_does_not_switch()
    {
        var gate = new TaskCompletionSource<IReadOnlyList<BudgetProjectInfo>>(TaskCreationOptions.RunContinuationsAsynchronously); var lookup = new FakeBudgetLookup { Gate = gate }; var cash = CashFlow(lookup: lookup); var workspace = new MainWorkspaceViewModel(new(new FakeCompanies()), new(new FakeProjects(), new FakeLookup(), TimeProvider.System), Budget(), Actual(), Forecast(), Variance(), ForecastAnalytics(), cash);
        var navigation = workspace.NavigateAsync(WorkspaceSection.CostCashFlow); workspace.SelectedSection.Should().Be(WorkspaceSection.Companies); gate.SetResult([]); await navigation; cash.LastProjectsReloadSucceeded.Should().BeTrue(); workspace.SelectedSection.Should().Be(WorkspaceSection.CostCashFlow);
        var failedCash = CashFlow(lookup: new() { Failure = true }); var failed = new MainWorkspaceViewModel(new(new FakeCompanies()), new(new FakeProjects(), new FakeLookup(), TimeProvider.System), Budget(), Actual(), Forecast(), Variance(), ForecastAnalytics(), failedCash); await failed.NavigateAsync(WorkspaceSection.CostCashFlow); failedCash.LastProjectsReloadSucceeded.Should().BeFalse(); failed.SelectedSection.Should().Be(WorkspaceSection.Companies);
    }
    [Fact]
    public async Task Busy_cost_cash_flow_blocks_navigation_and_recovery()
    {
        var project = new BudgetProjectInfo(Guid.NewGuid(), "Gym", "PLN", true); var service = new FakeCashFlow(); var cash = CashFlow(service, new() { Items = [project] }); var workspace = new MainWorkspaceViewModel(new(new FakeCompanies()), new(new FakeProjects(), new FakeLookup(), TimeProvider.System), Budget(), Actual(), Forecast(), Variance(), ForecastAnalytics(), cash); await cash.ReloadProjectsAsync(); service.Gate = new(TaskCreationOptions.RunContinuationsAsynchronously);
        var selecting = cash.SelectProjectAsync(project); cash.IsBusy.Should().BeTrue(); cash.CanNavigate.Should().BeFalse(); workspace.CanNavigate.Should().BeFalse(); workspace.CanOpenRecovery.Should().BeFalse(); service.Gate.SetResult(service.Value(project.Id)); await selecting; cash.IsBusy.Should().BeFalse(); workspace.CanNavigate.Should().BeTrue(); workspace.CanOpenRecovery.Should().BeTrue();
    }
